<script setup>import{onMounted,ref,watch}from'vue';import api from '../../../services/api';import{useAuthStore}from'../../../stores/auth';import FormErrors from '../../../components/ui/FormErrors.vue';const auth=useAuthStore(),users=ref([]),loading=ref(true),error=ref(null),search=ref(''),status=ref(''),page=ref(1),lastPage=ref(1);let timer;async function load(){loading.value=true;error.value=null;try{const response=await api.get('/v1/platform/users',{params:{search:search.value,status:status.value,page:page.value}});users.value=response.data.data.data;lastPage.value=response.data.data.last_page}catch(e){error.value=e}finally{loading.value=false}}watch([search,status],()=>{page.value=1;clearTimeout(timer);timer=setTimeout(load,300)});onMounted(load);const date=v=>new Intl.DateTimeFormat(undefined,{dateStyle:'medium'}).format(new Date(v));</script><template><div><header class="page-header"><div><p class="eyebrow">Platform administration</p><h1>System Users</h1><p>Manage administrators who can access the SaaS platform workspace.</p></div><RouterLink class="btn" :to="{name:'admin.users.create'}">+ Add Administrator</RouterLink></header><FormErrors :error="error"/><section class="admin-card"><div class="mb-5 grid gap-3 md:grid-cols-[1fr_180px_auto]"><input v-model="search" class="filter-input" placeholder="Search administrators..."><select v-model="status" class="filter-input"><option value="">All statuses</option><option value="active">Active</option><option value="inactive">Inactive</option></select><RouterLink class="btn-secondary text-center" :to="{name:'admin.roles'}">Roles &amp; Permissions</RouterLink></div><p v-if="loading" class="loading-state">Loading administrators...</p><div v-else class="table-wrap"><table><thead><tr><th>Administrator</th><th>Roles</th><th>Status</th><th>Created</th><th>Actions</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td><p class="font-semibold">{{user.name}}</p><p class="text-xs text-slate-500">{{user.email}}</p></td><td><span v-for="role in user.platform_roles" :key="role.id" class="badge badge-green mr-1">{{role.name}}</span></td><td><span :class="['badge',user.status==='active'?'badge-green':'badge-rose']">{{user.status}}</span></td><td>{{date(user.created_at)}}</td><td><span v-if="user.id===auth.user?.id" class="badge badge-amber">Current account</span><RouterLink v-else class="btn-secondary" :to="{name:'admin.users.edit',params:{id:user.id}}">Edit</RouterLink></td></tr></tbody></table><p v-if="!users.length" class="empty-state">No administrators found.</p></div><div class="mt-5 flex justify-between"><button class="btn-secondary" :disabled="page<=1" @click="page--;load()">Previous</button><span class="text-sm">Page {{page}} of {{lastPage}}</span><button class="btn-secondary" :disabled="page>=lastPage" @click="page++;load()">Next</button></div></section></div></template>
